header, main, footer { max-width: 1100px; margin: 0 auto; padding: 1rem; }
h1 { margin: .2rem 0; font-size: 2rem; }
.tag { color: var(--muted); margin-top: 0; }
.disclaimer { background:#fff6e0; border-left:4px solid #e0a100; padding:.6rem .8rem; font-size:.95rem; }
.mode { font-size:.85rem; color:var(--muted); margin-top:.4rem; }
.card { background:#fff; border-radius:10px; padding:1rem 1.2rem; margin:1rem 0; box-shadow:0 1px 3px #0001; }
label { display:block; margin:.5rem 0; }
label.inline { display:inline-block; margin-right:1rem; }
input:not([type=checkbox]), select { width:100%; padding:.5rem; font-size:1rem; border:1px solid #ccd; border-radius:6px; }
.sample { display:flex; gap:.6rem; margin-bottom:.8rem; }
.sample select { flex:1; }
button { font-size:1rem; padding:.6rem 1rem; border-radius:6px; border:1px solid var(--accent); background:#fff; color:var(--accent); cursor:pointer; }
button.primary, form button { background:var(--accent); color:#fff; }
.cols { display:grid; grid-template-columns:1fr 1fr; gap:1rem; align-items:start; }
@media (max-width: 760px) { .cols { grid-template-columns:1fr; } }
.grounded { border-top:4px solid var(--ok); }
.baseline { border-top:4px solid #999; }
ol li { margin-bottom:.8rem; }
.why { color:var(--muted); font-size:.92rem; }
.badge { white-space:nowrap; display:inline-block; font-size:.75rem; padding:.1rem .4rem; border-radius:4px; background:#eee; margin-left:.3rem; }
.badge.ok { background:#e2f4ea; color:var(--ok); } .badge.bad { background:#f8e3e3; color:var(--bad); }
table { width:100%; border-collapse:collapse; } th, td { text-align:left; padding:.4rem; border-bottom:1px solid #eee; }
fieldset { margin:.6rem 0 1rem; border:1px solid #ccd; border-radius:6px; }
.mono { font-family: ui-monospace, monospace; font-size:.82rem; }
footer { color:var(--muted); font-size:.85rem; }
button:disabled { cursor:not-allowed; opacity:.55; }
button:focus-visible, select:focus-visible, input:focus-visible, summary:focus-visible { outline:3px solid #39236b; outline-offset:3px; }
.week-range { color:var(--muted); margin-top:-.6rem; }
.week-controls { display:flex; gap:.8rem; align-items:end; flex-wrap:wrap; margin:1rem 0; }
.week-controls label { flex:1 1 180px; margin:0; }
.week-controls button { min-height:44px; }
.week-days { list-style:none; margin:1rem 0; padding:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:1rem; }
.week-day { border:1px solid #d8dfdc; border-radius:8px; margin:0; padding:.9rem; min-width:0; break-inside:avoid; }
.week-day h3 { display:flex; gap:.5rem; flex-wrap:wrap; justify-content:space-between; align-items:baseline; font-size:1.05rem; margin:0 0 .8rem; }
.week-day time { font-size:.85rem; font-weight:normal; color:var(--muted); }
.scheduled-pick + .scheduled-pick { border-top:1px solid #dde3df; margin-top:1rem; padding-top:1rem; }
.scheduled-pick h4 { margin:.3rem 0; font-size:1rem; overflow-wrap:anywhere; }
.scheduled-pick .why { margin:.45rem 0; overflow-wrap:anywhere; }
.scheduled-pick .badge { margin:0 .3rem .1rem 0; }
.pick-control { margin-bottom:0; color:var(--muted); font-size:.85rem; }
.pick-control select { margin-top:.25rem; }
.open-day { color:var(--muted); margin:.3rem 0; }
.open-day span { display:block; font-size:.85rem; }
.omitted-picks { list-style:none; padding:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:1rem; }
.omitted-picks li { border:1px dashed #9da9a1; border-radius:8px; padding:.8rem; min-width:0; break-inside:avoid; }
.handoff-note { font-size:.9rem; padding:.7rem; border-left:3px solid #e0a100; background:#fff6e0; }
.error { color:var(--bad); font-weight:600; }
.error:empty, #weekStatus:empty { display:none; }
.original-evidence > summary { cursor:pointer; padding:.6rem; color:var(--muted); }
@media (max-width: 600px) {
  .week-days, .omitted-picks { grid-template-columns:1fr; }
  .sample { flex-wrap:wrap; }
  .sample select { flex-basis:100%; }
  .week-controls button { flex:1 1 140px; }
}
@media print {
  @page { margin:14mm; }
  body { background:#fff; color:#111; font-size:10pt; }
  header, main, footer { max-width:none; padding:0; }
  header h1 { font-size:20pt; }
  header .tag, header #mode, .taste-form, .original-evidence, .week-controls, .pick-control, .organizer-help, .calendar-export { display:none !important; }
  .card { box-shadow:none; border-radius:0; margin:.7rem 0; padding:0; }
  #weekOrganizer { border-top:0; }
  #weekTitle { margin-bottom:.4rem; }
  .week-days, .omitted-picks { display:block; }
  .week-day, .omitted-picks li { margin-bottom:.6rem; padding:.55rem; break-inside:avoid; }
  .week-day h3 { margin-bottom:.3rem; }
  .week-day .why, .handoff-note { font-size:9pt; }
  .disclaimer { font-size:9pt; }
  #weekSource { color:#111; font-weight:600; }
  footer { margin-top:.7rem; font-size:8pt; }
}

import assert from "node:assert/strict";
import test from "node:test";
import { createWeekPlan, setPickDay, setWeek } from "../static/week_plan.mjs";
import { makeWeekFile, readWeekFile } from "../static/week_file.mjs";
import { createVenueFollowup } from "../static/venue_followup.mjs";
import { makeVenueNoteFile, readVenueNoteFile, VENUE_NOTE_BYTE_LIMIT } from "../static/venue_note_file.mjs";

const copy = (value) => structuredClone(value);
const now = new Date("2026-10-08T18:00:00.000Z");
function fixture() {
  const counts = { picks: 2, with_qloo_entity_id: 2, with_affinity_evidence: 0, constraint_checked: 2, unsafe_candidates_rejected: 0 };
  const inputs = { cuisines: ["Fictional"], music: [], films: [], city: "Authored fixture", constraints: ["soft_foods", "wheelchair"] };
  const response = {
    mock: true, plan: {
      meals: [
        { day: "Monday", kind: "restaurant", entity_id: "FIX-same", name: "Fixture café 海", why: "Original first occurrence; ask the venue.", affinity: null },
        { day: "Tuesday", kind: "restaurant", entity_id: "FIX-same", name: "Fixture café 海", why: "Different original occurrence.", affinity: null },
      ], outing: null, notes: ["Synthetic input; no venue finding."], rejected: [],
    },
    comparison: { constraints: inputs.constraints, grounded: counts, llm_only: counts },
    llm_only: { meals: [], outing: { day: "Friday", name: "Ungrounded fixture", why: "No source." } },
    trace: [{ tool: "authored_fixture", args: { witness: "original" }, result_summary: "Fictional input" }],
  };
  const origin = { response, inputs, receivedAt: "2026-10-08T17:00:00.000Z", calendarId: "0123456789abcdef0123456789abcdef" };
  const state = createWeekPlan(response, "2026-12-28");
  return { origin, state, model: createVenueFollowup(state) };
}
function reopened(context, state = context.state) {
  const original = readWeekFile(makeWeekFile({ ...context.origin, state }, now).text);
  return { origin: { response: original.response, inputs: original.inputs, receivedAt: original.receivedAt, calendarId: original.calendarId },
    state: original.state, model: createVenueFollowup(original.state) };
}
function record(context, key = "pick-0", reply = "A recorded reply") {
  const entry = context.model.entries(context.state).find((row) => row.key === key);
  context.model.setField(context.state, key, entry.date, "reply", reply);
  return entry;
}

test("companion restores all exact records across reopening, omitted visits and other dates", () => {
  const first = fixture();
  record(first, "pick-0", "\nRéponse 海 🧭\n  keep this space ");
  first.model.setField(first.state, "pick-0", "2026-12-28", "status", "reply_recorded");
  first.model.setField(first.state, "pick-0", "2026-12-28", "question", "Revised question?\r\nNot yet answered.");
  const later = { ...first, state: setWeek(setPickDay(first.state, "pick-1", "Monday"), "2027-01-04") };
  record(later, "pick-1", "Another dated occurrence");
  first.model.setField(later.state, "pick-1", "2027-01-04", "nextStep", "Call later\n  留");
  const notesBefore = first.model.snapshotRecords(), originalBefore = JSON.stringify(first.origin);
  const output = makeVenueNoteFile(later, now);
  const target = reopened(later, setPickDay(later.state, "pick-1", null));
  assert.deepEqual(target.model.snapshotRecords(), []);
  const prepared = readVenueNoteFile(output.text, target);
  assert.deepEqual(target.model.snapshotRecords(), [], "reading alone cannot replace notes");
  const stateBefore = target.state;
  target.model.replaceRecords(prepared.records);
  assert.equal(target.state, stateBefore);
  assert.deepEqual(target.model.snapshotRecords(), notesBefore);
  const earlier = setWeek(target.state, "2026-12-28");
  const old = target.model.entries(earlier).find((row) => row.key === "pick-0");
  assert.equal(old.note.reply, "\nRéponse 海 🧭\n  keep this space ");
  assert.equal(old.questionsChangedAfterReply, true);
  assert.equal(old.note.status, "follow_up");
  assert.notEqual(old.note.replyQuestions, old.questionText);
  assert.equal(JSON.stringify(first.origin), originalBefore);
});

test("same venue, day and visible name keep their separate original occurrence identities", () => {
  const source = fixture(); source.state = setPickDay(source.state, "pick-1", "Monday");
  record(source, "pick-0", "First visit's answer");
  record(source, "pick-1", "Second visit's answer");
  const target = reopened(source);
  target.model.replaceRecords(readVenueNoteFile(makeVenueNoteFile(source, now).text, target).records);
  assert.deepEqual(target.model.entries(target.state).map((row) => row.note.reply), ["First visit's answer", "Second visit's answer"]);
  const moved = setPickDay(target.state, "pick-0", "Friday");
  assert.equal(target.model.entries(moved).find((row) => row.key === "pick-0").note.reply, "");
  assert.equal(target.model.entries(moved).find((row) => row.key === "pick-1").note.reply, "Second visit's answer");
  assert.equal(target.model.entries(target.state)[0].note.reply, "First visit's answer");
});

test("late invalid or duplicate records cannot partially replace current notes", () => {
  const target = fixture(); record(target, "pick-0", "Current note must survive");
  const before = target.model.snapshotRecords();
  const rows = copy(before); rows[0].note.reply = "Incoming replacement";
  const invalid = [
    [...rows, { ...rows[0], date: "2026-02-30" }],
    [...rows, { ...rows[0], key: "pick-99" }],
    [...rows, copy(rows[0])],
    [{ ...rows[0], extra: "unsupported" }],
    [{ ...rows[0], note: { ...rows[0].note, extra: "unsupported" } }],
  ];
  for (const records of invalid) {
    assert.throws(() => target.model.replaceRecords(records));
    assert.deepEqual(target.model.snapshotRecords(), before);
  }
});

test("unsupported field types and inconsistent reply history are refused literally", () => {
  const context = fixture(); record(context);
  const file = JSON.parse(makeVenueNoteFile(context, now).text);
  const originals = context.model.snapshotRecords();
  const edits = [
    { status: ["awaiting_reply"] }, { status: "constructor" }, { question: 2 },
    { question: "q".repeat(2001) }, { reply: "r".repeat(2001) }, { nextStep: "n".repeat(501) },
    { replyQuestions: null }, { replyQuestions: 42 }, { replyQuestions: "q".repeat(2001) },
    { reply: " \n", replyQuestions: "Earlier" },
    { status: "reply_recorded", question: "Different?", replyQuestions: "Earlier?" },
  ];
  for (const changes of edits) {
    const value = copy(file); Object.assign(value.records[0].note, changes);
    assert.throws(() => readVenueNoteFile(JSON.stringify(value), context));
    assert.deepEqual(context.model.snapshotRecords(), originals);
  }
});

test("full origin equality accepts reordered JSON keys but refuses another request or response", () => {
  const context = fixture(); record(context);
  const file = JSON.parse(makeVenueNoteFile(context, now).text);
  const mutations = [
    (v) => { v.origin.receivedAt = "2026-10-08T17:00:00.001Z"; },
    (v) => { v.origin.calendarId = "fedcba9876543210fedcba9876543210"; },
    (v) => { v.origin.inputs.music.push("Other input"); },
    (v) => { v.origin.response.trace[0].args.witness = "another origin"; },
    (v) => { v.origin.response.plan.meals.reverse(); },
    (v) => { v.origin.response.mock = false; },
    (v) => { v.origin.response.plan.meals[0].affinity = Infinity; },
  ];
  for (const mutate of mutations) {
    const value = copy(file); mutate(value);
    const text = JSON.stringify(value).replace('"affinity":null', value.origin.response.plan.meals[0].affinity === Infinity ? '"affinity":1e309' : '"affinity":null');
    assert.throws(() => readVenueNoteFile(text, context), /different accepted plan|finite JSON/);
  }
  const reordered = copy(file);
  reordered.origin = Object.fromEntries(Object.entries(reordered.origin).reverse());
  reordered.origin.response = Object.fromEntries(Object.entries(reordered.origin.response).reverse());
  assert.deepEqual(readVenueNoteFile(JSON.stringify(reordered), context).records, context.model.snapshotRecords());
});

test("bounded v1 file admission and explicit empty replacement preserve the original week codec", () => {
  const context = fixture(); record(context);
  const originalWeek = makeWeekFile({ ...context.origin, state: context.state }, now).text;
  const file = JSON.parse(makeVenueNoteFile(context, now).text);
  const invalid = [
    { ...file, format: "tastetable.venue-notes.v2" },
    { ...file, savedAt: "not a timestamp" },
    { ...file, records: {} },
    { ...file, records: Array(257).fill(file.records[0]) },
    { ...file, unexpected: 1 },
  ];
  for (const value of invalid) assert.throws(() => readVenueNoteFile(JSON.stringify(value), context));
  assert.throws(() => readVenueNoteFile("{", context), /valid JSON/);
  assert.throws(() => readVenueNoteFile(" ".repeat(VENUE_NOTE_BYTE_LIMIT + 1), context), /2 MiB/);
  assert.doesNotThrow(() => readVenueNoteFile("\uFEFF" + JSON.stringify(file), context));
  assert.equal(makeWeekFile({ ...context.origin, state: context.state }, now).text, originalWeek);
  const empty = { ...file, records: [] };
  const preview = readVenueNoteFile(JSON.stringify(empty), context);
  assert.equal(context.model.snapshotRecords().length, 1);
  context.model.replaceRecords(preview.records);
  assert.deepEqual(context.model.snapshotRecords(), []);
  assert.equal(makeWeekFile({ ...context.origin, state: context.state }, now).text, originalWeek);
});

test("source-bound model guard and exact existing field limits remain in the new file boundary", () => {
  const context = fixture();
  const entry = context.model.entries(context.state)[0];
  const question = "🧭".repeat(1000), reply = "Ré".repeat(1000), nextStep = " ".repeat(500);
  context.model.setField(context.state, entry.key, entry.date, "question", question);
  context.model.setField(context.state, entry.key, entry.date, "reply", reply);
  context.model.setField(context.state, entry.key, entry.date, "nextStep", nextStep);
  const result = readVenueNoteFile(makeVenueNoteFile(context, now).text, context);
  assert.equal(result.records[0].note.question, question);
  assert.equal(result.records[0].note.reply, reply);
  assert.equal(result.records[0].note.nextStep, nextStep);
  const foreign = fixture();
  assert.throws(() => makeVenueNoteFile({ ...context, state: foreign.state }, now), /different accepted plan/);
  assert.ok(Object.isFrozen(result.records) && Object.isFrozen(result.records[0].note));
});

import assert from "node:assert/strict";
import test from "node:test";
import { createWeekPlan, resetDays, setPickDay, setWeek } from "../static/week_plan.mjs";
import { CONTACT_STATES, createVenueFollowup } from "../static/venue_followup.mjs";

function response() {
  return {
    mock: true,
    comparison: { constraints: ["soft_foods", "low_sodium", "wheelchair"] },
    plan: {
      meals: [
        { day: "Monday", kind: "restaurant", entity_id: "FIX-repeat", name: "Fictional café", why: "Soft foods: unknown (ask the venue)." },
        { day: "Tuesday", kind: "restaurant", entity_id: "FIX-repeat", name: "Fictional café", why: "Original second occurrence." },
      ],
      outing: { day: "Saturday", kind: "outing", entity_id: "FIX-museum", name: "Fictional museum", why: "Wheelchair: pass (fixture tag)." },
      notes: ["A synthetic, heuristic plan."], rejected: [],
    },
  };
}
const week = () => createWeekPlan(response(), "2026-12-30");

test("questions use the native purpose and constraints; original unknown explanation survives", () => {
  const state = week();
  const entries = createVenueFollowup(state).entries(state);
  assert.equal(entries.length, 3);
  assert.equal(entries[0].date, "2026-12-28");
  assert.equal(entries[0].questions.length, 4);
  assert.match(entries[0].questions[0], /2026-12-28/);
  assert.equal(entries[2].questions.length, 2);
  assert.match(entries[2].questions[1], /step-free/);
  assert.match(entries[0].pick.why, /unknown/);
});

test("a different date starts a separate note; returning restores only that occurrence's note", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "reply", "Monday response");
  const moved = setPickDay(initial, "pick-0", "Thursday");
  assert.equal(contacts.entries(moved).find((entry) => entry.key === "pick-0").note.reply, "");
  contacts.setField(moved, "pick-0", "2026-12-31", "reply", "Thursday response");
  assert.equal(contacts.entries(resetDays(moved))[0].note.reply, "Monday response");
  assert.equal(contacts.entries(moved).find((entry) => entry.key === "pick-0").note.reply, "Thursday response");
});

test("two occurrences sharing an entity and date retain distinct caregiver notes", () => {
  const initial = week(), state = setPickDay(initial, "pick-1", "Monday");
  const contacts = createVenueFollowup(initial);
  contacts.setField(state, "pick-0", "2026-12-28", "reply", "First visit");
  contacts.setField(state, "pick-1", "2026-12-28", "reply", "Second visit");
  const entries = contacts.entries(state);
  assert.deepEqual(entries.slice(0, 2).map((entry) => [entry.occurrence, entry.note.reply]), [[1, "First visit"], [2, "Second visit"]]);
});

test("omitted picks have no active contact card or exported note, and restore retains its date", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "reply", "Keep this original note");
  const omitted = setPickDay(initial, "pick-0", null);
  assert.equal(contacts.entries(omitted).length, 2);
  assert.doesNotMatch(contacts.text(omitted), /Keep this original note/);
  assert.throws(() => contacts.setField(omitted, "pick-0", "2026-12-28", "reply", "Stale edit"), /no longer scheduled/);
  assert.equal(contacts.entries(resetDays(omitted))[0].note.reply, "Keep this original note");
});

test("another week has separate notes even when weekday and occurrence are unchanged", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "status", "reply_recorded");
  const later = setWeek(initial, "2027-01-04");
  assert.equal(contacts.entries(later)[0].note.status, "not_contacted");
  assert.equal(contacts.entries(setWeek(later, "2026-12-30"))[0].note.status, "reply_recorded");
});

test("an identical newly accepted response cannot inherit or access the prior worksheet", () => {
  const initial = week(), replacement = week(), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "reply", "Old source response");
  assert.throws(() => contacts.entries(replacement), /different accepted plan/);
  assert.throws(() => contacts.text(replacement), /different accepted plan/);
  assert.equal(createVenueFollowup(replacement).entries(replacement)[0].note.reply, "");
});

test("source provenance cannot be relabeled while borrowing the original source objects", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  assert.throws(() => contacts.text({ ...initial, sourceMode: "live" }), /different accepted plan/);
});

test("an event still carrying the old date cannot update the newly scheduled visit", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  const moved = setPickDay(initial, "pick-0", "Thursday");
  assert.throws(() => contacts.setField(moved, "pick-0", "2026-12-28", "reply", "Stale DOM event"), /no longer scheduled/);
  assert.equal(contacts.entries(moved).find((entry) => entry.key === "pick-0").note.reply, "");
});

test("the printable export carries exact source, dates and labeled multiline caregiver notes", () => {
  const initial = week(), sourceBefore = JSON.stringify(initial), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "reply", "No answer yet.\nTry the venue again.");
  contacts.setField(initial, "pick-0", "2026-12-28", "nextStep", "Call on Friday.");
  contacts.setField(initial, "pick-0", "2026-12-28", "status", "follow_up");
  const output = contacts.text(initial);
  assert.match(output, /Demo plan: fictional venues/);
  assert.match(output, /Monday 2026-12-28 — Fictional café/);
  assert.match(output, /Soft foods: unknown \(ask the venue\)\./);
  assert.match(output, /Caregiver contact status: Needs follow-up/);
  assert.match(output, /Venue reply \/ your notes:\n  No answer yet\.\n  Try the venue again\./);
  assert.match(output, /not a safety check, reservation or confirmation by TasteTable/);
  assert.equal(JSON.stringify(initial), sourceBefore);
  assert.ok(!Object.values(CONTACT_STATES).some((value) => /safe|verified|confirmed/i.test(value)));
});

test("empty scheduled weeks cannot create an apparently populated call sheet", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  const empty = initial.picks.reduce((state, pick) => setPickDay(state, pick.key, null), initial);
  assert.deepEqual(contacts.entries(empty), []);
  assert.throws(() => contacts.text(empty), /at least one pick/);
});

test("unknown fields, status values and oversized notes do not modify a retained note", () => {
  const initial = week(), contacts = createVenueFollowup(initial);
  contacts.setField(initial, "pick-0", "2026-12-28", "reply", "Preserve me");
  for (const [field, value] of [["verified", "true"], ["status", "safe"], ["nextStep", "x".repeat(501)], ["reply", "x".repeat(2001)], ["reply", false]]) {
    assert.throws(() => contacts.setField(initial, "pick-0", "2026-12-28", field, value));
  }
  assert.equal(contacts.entries(initial)[0].note.reply, "Preserve me");
  assert.throws(() => { contacts.entries(initial)[0].note.reply = "mutated"; }, TypeError);
});

test("a reopened source retains its filename, age and unchanged-check label in the call sheet", () => {
  const state = week();
  const label = 'Saved copy opened from “caregiver-week.json” (saved 2026-10-08T12:00:00.000Z). Source labels and checks below are retained from the file; they have not been run again.';
  const contacts = createVenueFollowup(state, label);
  assert.ok(contacts.text(state).includes(label));
  assert.ok(contacts.sourceLabel.includes(label));
  assert.ok(contacts.text(setWeek(state, "2027-01-04")).includes(label));
  assert.equal(contacts.entries(state)[0].note.reply, "");
});

test("editable questions remain literal, occurrence/date-bound text alongside unchanged source checks", () => {
  const state = week(), before = JSON.stringify(state), contacts = createVenueFollowup(state);
  const question = 'Is the side entrance available?\nCan we visit before 1pm? <script>literal text</script>';
  contacts.setField(state, "pick-0", "2026-12-28", "question", question);
  const entry = contacts.entries(state)[0];
  assert.equal(entry.questionText, question);
  assert.deepEqual(entry.questions, question.split("\n"));
  assert.ok(contacts.text(state).includes(question.split("\n")[1]));
  assert.notEqual(contacts.entries(state)[1].questionText, question);
  assert.notEqual(contacts.entries(setPickDay(state, "pick-0", "Thursday")).find((item) => item.key === "pick-0").questionText, question);
  assert.equal(contacts.entries(state)[0].questionText, question);
  assert.equal(JSON.stringify(state), before);
});

test("revising questions retains the earlier reply with its actual question context and a follow-up hold", () => {
  const state = week(), contacts = createVenueFollowup(state);
  const original = contacts.entries(state)[0].questionText;
  contacts.setField(state, "pick-0", "2026-12-28", "reply", "The venue replied about the original visit.");
  contacts.setField(state, "pick-0", "2026-12-28", "status", "reply_recorded");
  contacts.setField(state, "pick-0", "2026-12-28", "question", "Is the side entrance open after 6pm?");
  const revised = contacts.entries(state)[0];
  assert.equal(revised.note.status, "follow_up");
  assert.equal(revised.questionsChangedAfterReply, true);
  assert.equal(revised.note.replyQuestions, original);
  assert.equal(revised.note.reply, "The venue replied about the original visit.");
  assert.match(contacts.text(state), /Earlier reply \/ notes \(for the previous questions\)/);
  assert.ok(contacts.text(state).includes(original.split("\n")[0]));
  assert.throws(() => contacts.setField(state, "pick-0", "2026-12-28", "status", "reply_recorded"), /revised questions/);
  contacts.setField(state, "pick-0", "2026-12-28", "nextStep", "Ask again.");
  assert.equal(contacts.entries(state)[0].questionsChangedAfterReply, true);
  contacts.setField(state, "pick-0", "2026-12-28", "reply", "New reply about the side entrance after 6pm.");
  contacts.setField(state, "pick-0", "2026-12-28", "status", "reply_recorded");
  assert.equal(contacts.entries(state)[0].questionsChangedAfterReply, false);
  assert.equal(contacts.entries(state)[0].note.replyQuestions, "Is the side entrance open after 6pm?");
  assert.doesNotMatch(contacts.text(state), /Earlier reply \/ notes \(for the previous questions\)/);
});

test("unchanged questions preserve status; returning to the earlier questions removes only the mismatch", () => {
  const state = week(), contacts = createVenueFollowup(state), original = contacts.entries(state)[0].questionText;
  contacts.setField(state, "pick-0", "2026-12-28", "reply", "An earlier answer.");
  contacts.setField(state, "pick-0", "2026-12-28", "status", "reply_recorded");
  contacts.setField(state, "pick-0", "2026-12-28", "question", original);
  assert.equal(contacts.entries(state)[0].note.status, "reply_recorded");
  contacts.setField(state, "pick-0", "2026-12-28", "question", "Changed question.");
  contacts.setField(state, "pick-0", "2026-12-28", "question", original);
  assert.equal(contacts.entries(state)[0].questionsChangedAfterReply, false);
  assert.equal(contacts.entries(state)[0].note.status, "follow_up");
});

